let managedQueueName="";
const token=()=>document.getElementById("operator-token").value.trim();
function showEditorError(message){const box=$("editor-alert");box.textContent=message;box.hidden=!message}
async function request(url,options={}){const response=await fetch(url,options),body=await response.json().catch(()=>({}));if(!response.ok)throw new Error(body.error?.message||`${response.status} ${response.statusText}`);return{response,body}}
function queueFromPlan(declaration){
  const plan=declaration.plan||{},stream=plan.stream||{},consumer=plan.consumer||{},metadata=stream.metadata||{};
  const labels={};Object.entries(metadata).forEach(([key,value])=>{const prefix="rabbit-jetstream.io/label.";if(key.startsWith(prefix))labels[key.slice(prefix.length)]=value});
  const spec={replicas:stream.replicas||3,storage:stream.storage||"file",retention:{maxAge:`${stream.maxAgeNanos||0}ns`,maxBytes:`${stream.maxBytes||0}B`,maxMessages:stream.maxMessages||0},delivery:{ackWait:`${consumer.ackWaitNanos||30000000000}ns`,maxDeliver:consumer.maxDeliver||5}};
  if((plan.routing||[]).length)spec.bindings=plan.routing.map(item=>({exchange:item.exchange,type:item.type,...(item.keys?.length?{keys:item.keys}:{})}));else spec.subjects=(stream.subjects||[]).filter(subject=>subject!==`rjs.q.${declaration.queue}.ingress`);
  if(plan.deadLetter)spec.deadLetter={queue:plan.deadLetter.queue};
  return{apiVersion:"rabbit-jetstream.io/v1alpha1",kind:"Queue",metadata:{name:declaration.queue,...(Object.keys(labels).length?{labels}:{})},spec};
}
function defaultQueue(){return{apiVersion:"rabbit-jetstream.io/v1alpha1",kind:"Queue",metadata:{name:"example"},spec:{subjects:["example.events"],replicas:3,storage:"file",retention:{maxAge:"24h",maxBytes:"1GiB",maxMessages:1000000},delivery:{ackWait:"30s",maxDeliver:5}}}}
function openEditor(document,existingName=""){$("editor-title").textContent=existingName?`Manage ${existingName}`:"Create or update queue";$('queue-document').value=JSON.stringify(document||defaultQueue(),null,2);managedQueueName=existingName;$('delete-controls').hidden=!existingName;$('delete-confirm').value="";$('delete-force').checked=false;showEditorError("");$('queue-editor').showModal()}
async function editQueue(name){try{const {body}=await request(`/api/v1/queues/${encodeURIComponent(name)}`);openEditor(queueFromPlan(body),name)}catch(error){showGlobal(error.message)}}
function showGlobal(message){const box=$("alert");box.textContent=message;box.hidden=false}
async function applyQueue(event){event.preventDefault();showEditorError("");const bearer=token();if(!bearer){showEditorError("Enter an operator bearer token before applying changes.");return}let document;try{document=JSON.parse($("queue-document").value)}catch(error){showEditorError(`Invalid JSON: ${error.message}`);return}const name=document?.metadata?.name;if(!name){showEditorError("metadata.name is required.");return}const endpoint=`/api/v1/queues/${encodeURIComponent(name)}`;let precondition;try{const lookup=await fetch(endpoint,{headers:{Accept:"application/json"}});if(lookup.status===404)precondition={"If-None-Match":"*"};else if(lookup.ok){const etag=lookup.headers.get("ETag");if(!etag)throw new Error("Management API did not return an ETag.");precondition={"If-Match":etag}}else{const body=await lookup.json().catch(()=>({}));throw new Error(body.error?.message||`${lookup.status} ${lookup.statusText}`)}}catch(error){showEditorError(error.message);return}
  $("queue-apply").disabled=true;try{await request(endpoint,{method:"PUT",headers:{Authorization:`Bearer ${bearer}`,"Content-Type":"application/json",...precondition},body:JSON.stringify(document)});$('queue-editor').close();await loadDashboard()}catch(error){showEditorError(error.message)}finally{$("queue-apply").disabled=false}}
async function deleteQueue(){showEditorError("");const bearer=token();if(!bearer){showEditorError("Enter an operator bearer token before deleting.");return}if($("delete-confirm").value!==managedQueueName){showEditorError("Deletion confirmation must exactly match the Queue name.");return}const endpoint=`/api/v1/queues/${encodeURIComponent(managedQueueName)}`;try{const lookup=await fetch(endpoint);if(!lookup.ok)throw new Error(`Unable to read current Queue revision (${lookup.status}).`);const etag=lookup.headers.get("ETag");if(!etag)throw new Error("Management API did not return an ETag.");$("queue-delete").disabled=true;await request(`${endpoint}${$("delete-force").checked?"?force=true":""}`,{method:"DELETE",headers:{Authorization:`Bearer ${bearer}`,"If-Match":etag,"X-RJS-Confirm-Queue":managedQueueName}});$('queue-editor').close();$('queue-dialog').close();await loadDashboard()}catch(error){showEditorError(error.message)}finally{$("queue-delete").disabled=false}}
$("queue-create").addEventListener("click",()=>openEditor(defaultQueue()));
$("queue-form").addEventListener("submit",applyQueue);
$("queue-delete").addEventListener("click",deleteQueue);
for(const id of ["editor-close","editor-cancel"])$(id).addEventListener("click",()=>$("queue-editor").close());
new MutationObserver(()=>{if(!$("queue-dialog").open||$("dialog-body").querySelector(".manage-action"))return;const name=$("dialog-title").textContent,section=document.createElement("section"),button=document.createElement("button");section.className="dialog-section manage-action";button.type="button";button.className="primary";button.textContent="Manage declaration";button.addEventListener("click",()=>editQueue(name));section.append(button);$("dialog-body").append(section)}).observe($("dialog-body"),{childList:true});
